{"output": "def transform(grid):
    """Extend rays rightward from the rightmost edge of each foreground object."""
    if not grid:
        return []
    h = len(grid)
    widths = [len(row) for row in grid]
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(widths[r]):
            if grid[r][c] == background or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            component = []
            while stack:
                y, x = stack.pop()
                component.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        if dy == 0 and dx == 0:
                            continue
                        ny, nx = y + dy, x + dx
                        if (0 <= ny < h and 0 <= nx < widths[ny]
                                and (ny, nx) not in seen
                                and grid[ny][nx] != background):
                            seen.add((ny, nx))
                            stack.append((ny, nx))
            rightmost = max(x for _, x in component)
            if rightmost == max(widths) - 1:
                continue
            edge_rows = {y for y, x in component if x == rightmost}
            for y in edge_rows:
                for x in range(rightmost + 1, widths[y]):
                    out[y][x] = 1
    return out

